import jax
import jax.numpy as jnp
from jax import random
import flax.linen as nn
from typing import Dict, Any

def _define_hyperparameters():
    """Define hyperparameter values for the CNN model."""
    return {
        'learning_rate': 0.001,
        'hidden_dim': 256,
        'dropout_rate': 0.2,
        'cnn_features': 128,
        'cnn_kernel_size': 7
    }

class SimpleCNN(nn.Module):
    """A simple 1D CNN for RNA sequence modeling."""
    d_output: int
    task_type: str
    cnn_features: int
    cnn_kernel_size: int
    hidden_dim: int
    dropout_rate: float

    @nn.compact
    def __call__(self, x, deterministic=True):
        # Input shape: (batch, seq_len, features=4)

        # 1D Convolutional Layer to find motifs
        x = nn.Conv(features=self.cnn_features, kernel_size=(self.cnn_kernel_size,))(x)
        x = nn.relu(x)

        # Global Max Pooling to capture the most important features
        x = jnp.max(x, axis=1) # Shape: (batch, cnn_features)

        # Dense layers for prediction
        x = nn.Dense(features=self.hidden_dim)(x)
        x = nn.relu(x)
        x = nn.Dropout(rate=self.dropout_rate)(x, deterministic=deterministic)

        x = nn.Dense(features=self.d_output)(x)

        # Squeeze output for regression tasks
        if self.task_type == "regression":
            return x.squeeze(-1)
        else:
            return x

class CNNNetworkWrapper:
    """Wrapper that implements the required init and apply interface."""
    def __init__(self, d_output, task_type, cnn_features, cnn_kernel_size, hidden_dim, dropout_rate):
        self.network = SimpleCNN(
            d_output=d_output,
            task_type=task_type,
            cnn_features=cnn_features,
            cnn_kernel_size=cnn_kernel_size,
            hidden_dim=hidden_dim,
            dropout_rate=dropout_rate
        )

    def init(self, rng_key, dummy_input):
        params_key, dropout_key = random.split(rng_key)
        variables = self.network.init({'params': params_key, 'dropout': dropout_key},
                                     dummy_input, deterministic=True)
        return variables['params']

    def apply(self, params, x, deterministic=True, rng_key=None):
      if deterministic:
          return self.network.apply({'params': params}, x, deterministic=True)
      else:
          if rng_key is None:
              rng_key = random.PRNGKey(0)
          return self.network.apply({'params': params}, x, deterministic=False, rngs={'dropout': rng_key})


def create_network(hparams: Dict[str, Any]):
    """Create and return the custom CNN network."""
    return CNNNetworkWrapper(
        d_output=hparams.get("d_output"),
        task_type=hparams.get("task_type"),
        cnn_features=hparams.get("cnn_features"),
        cnn_kernel_size=hparams.get("cnn_kernel_size"),
        hidden_dim=hparams.get("hidden_dim"),
        dropout_rate=hparams.get("dropout_rate")
    )
